import{_t as e,it as t,n,rt as r}from"./chunks/framework.DJ0NkIPM.js";var i=JSON.parse(`{"title":"Uçuş Verilerini Yeniden Oynat","description":"","frontmatter":{},"headers":[],"relativePath":"tr/qgc-user-guide/fly_view/replay_flight_data.md","filePath":"tr/qgc-user-guide/fly_view/replay_flight_data.md"}`),a={name:`tr/qgc-user-guide/fly_view/replay_flight_data.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="ucus-verilerini-yeniden-oynat" tabindex="-1">Uçuş Verilerini Yeniden Oynat <a class="header-anchor" href="#ucus-verilerini-yeniden-oynat" aria-label="Permalink to “Uçuş Verilerini Yeniden Oynat”">​</a></h1><div class="warning custom-block"><p class="custom-block-title custom-block-title-default">WARNING</p><p>Bu özellik, öncelikle ** otopilot geliştiricileri ** / ** araç tasarlayıcıları ** için tasarlanmıştır. Bu özellik, sadece bilgisayar sürümlerinde desteklenmektedir (Windows, Linux, Mac OS).</p></div><p>The <em>Replay Flight Data</em> feature allows users to replay a telemetry log, enabling review of past or problematic flights. Uçuş başlatılabilir, duraklatılabilir, durdurulabilir, yeniden başlatılabilir vb.</p><div class="info custom-block"><p class="custom-block-title custom-block-title-default">INFO</p><p><em>QGroundControl</em> uçuş tekrarını aktif bir bağlantı gibi görür. Oynatmayı duraklattığınızda / durdurduğunuzda, yer istasyonu &quot;İletişim Kaybı&quot; olarak rapor edecek ve bağlantının kesilmesini veya daha fazla komut bekleyecektir.</p></div><p>Bir uçuşu tekrar etmek için:</p><ol><li><p>Tüm aktif bağlantıları kesin.</p></li><li><p><strong>Application Settings &gt; General &gt; Fly View</strong>&#39;i seçin</p></li><li><p>Ekranın altında uçuşu tekrar oynat butonunu görebilmek için <strong>Show Telemetry Log Replay Status Bar</strong>&#39;ı işaretleyin.</p></li><li><p><em>file selection</em> seçeneğine erişmek için <strong>Load Telemetry Log</strong>&#39;a tıklayın.</p><ul><li>Tekrar oynatılması için uygun telemetri kayıtlarından bir kayıt dosyası seçin.</li><li>QGroundControl *, kayıtı hemen oynatmaya başlar.</li></ul></li><li><p>Bir kayıt yüklendiğinde şunları kullanabilirsiniz:</p><ul><li>Oynatmayı durdurmak ve yeniden başlatmak için <strong>Pause/Play</strong> butonuna basın.</li><li>Kayıtta yeni bir konuma ilerlemek için <em>Slider</em>.</li><li><em>Rate</em> selector to choose the playback speed.</li></ul></li><li><p>To stop replay (i.e. to load a new file to replay), first pause the flight, and then select <strong>Disconnect</strong> (when it appears). After disconnecting, the <strong>Load Telemetry Log</strong> button will be displayed.</p></li></ol><div class="tip custom-block"><p class="custom-block-title custom-block-title-default">TIP</p><p><a href="./../analyze_view/mavlink_inspector.html"> MAVLink Inspector </a> &#39;ı kullanarak devam eden tekrarı daha ayrıntılı olarak inceleyebilirsiniz.</p></div>`,7)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};